  ('page', 'terms', 'Terms of use', 'draft', NULL, 'secretariat', NULL, 20, '2026-10-01 05:00:00.000'),
  ('page', 'accessibility', 'Accessibility', 'draft', NULL, 'secretariat', NULL, 30, '2026-10-01 05:00:00.000')
;

